        if len(mA)<120:
            return {}
        synth=0.3333*mA+0.6667*mB+0.1667*mC
        spread=synth-mI
        # mask nans early
        valid=spread[np.isfinite(spread)]
        if len(valid)<100:
            return {}
        mu=np.nanmean(valid)
        sd=np.nanstd(valid)
        if not np.isfinite(mu) or not np.isfinite(sd) or sd<1.5:
            return {}
        cur_spread=spread[-1]
        if not np.isfinite(cur_spread):
            return {}
        z=(cur_spread-mu)/sd
        # state for fixed horizon holding
        if 'hold' not in obs.state:
            obs.state['hold']=0
            obs.state['pos']=0.0
        # countdown hold
        if obs.state['hold']>0:
            obs.state['hold']-=1
            # if hold expires, check if should exit or extend
            if obs.state['hold']==0:
                if abs(z)<0.6:
                    obs.state['pos']=0.0
                else:
                    # if still stretched same direction, keep holding a bit longer
                    if (obs.state['pos']>0 and z>1.0) or (obs.state['pos']<0 and z<-1.0):
                        obs.state['hold']=3
                    else:
                        obs.state['pos']=0.0
            return {'IDX': float(obs.state['pos'])}
        # not in hold, look for entry
        if z>1.8:
            obs.state['pos']=1.0
            obs.state['hold']=5
            return {'IDX': 1.0}
        elif z<-1.8:
            obs.state['pos']=-1.0
            obs.state['hold']=5
            return {'IDX': -1.0}
        elif abs(z)<0.5:
            obs.state['pos']=0.0
            return {'IDX': 0.0}
        else:
            # keep previous (flat)
            if obs.state['pos']!=0:
                return {'IDX': float(obs.state['pos'])}
            return {}
    except:
        return {}

def signal(obs):
    try:
        # need enough history: 250 steps
        n = 250
        mA = obs.hist('A','mid', n)
        mB = obs.hist('B','mid', n)
        mC = obs.hist('C','mid', n)
        mI = obs.hist('IDX','mid', n)
        if mA is None or mB is None or mC is None or mI is None:
            return {}
        if len(mA) < 200:
            return {}
        synth = 0.3333*mA + 0.6667*mB + 0.1667*mC
        spread = synth - mI
        # current z
        valid = spread[np.isfinite(spread)]
        if len(valid) < 150:
            return {}
        mu = np.nanmean(valid[-150:])
        sd = np.nanstd(valid[-150:])
        if not np.isfinite(mu) or not np.isfinite(sd) or sd < 1.0:
            return {}
        cur = spread[-1]
        if not np.isfinite(cur):
            return {}
        z = (cur - mu) / sd

        # estimate recent correlation between spread and 50-step forward IDX return
        # use past data where forward return is already realised (ends before now)
        # we need at least 80 pairs
        h = 50
        # we can only use pairs where i + h < len(spread)-1 (current index is last)
        # take window of last 120 spreads before the most recent h steps
        # spread indices 0..n-1, current is n-1, forward from n-1 is unknown, so last usable i = n-1-h
        usable_len = n - h - 10
        # need 80 pairs ending at usable_len
        start = max(0, usable_len - 100)
        xs = []
        ys = []
        # collect
        # use numpy vectorized for speed
        # slice
        s_slice = spread[start:usable_len]
        # fwd returns: mI[i+h]-mI[i]
        fwd = mI[start+h:usable_len+h] - mI[start:usable_len]
        # mask finite
        mask = np.isfinite(s_slice) & np.isfinite(fwd)
        x = s_slice[mask]
        y = fwd[mask]
        corr = 0.0
        if len(x) > 30 and np.nanstd(x) > 1e-6 and np.nanstd(y) > 1e-6:
            # correlation
            xm = x - np.mean(x)
            ym = y - np.mean(y)
            denom = np.sqrt(np.sum(xm*xm)*np.sum(ym*ym))
            if denom > 1e-9:
                corr = float(np.sum(xm*ym)/denom)
            else:
                corr = 0.0
        else:
            corr = 0.0

        # decide direction: if corr positive, mean-reversion (long IDX when spread high)
        # if corr negative, momentum (short IDX when spread high)
        # dead zone for uncertain corr
        if corr > 0.15:
            direction = 1.0
        elif corr < -0.15:
            direction = -1.0
        else:
            # if uncertain, use long-term prior (mean reversion) but with smaller size
            # check if |corr| small, stay flat to avoid whipsaw unless |z| very large
            if abs(z) < 2.2:
                return {}
            direction = 1.0 if corr >= 0 else -1.0

        # scale target by z, with direction
        raw = direction * z / 2.5
        raw = float(np.clip(raw, -1.0, 1.0))
        # dead zone for small signals to save costs
        if abs(raw) < 0.45:
            raw = 0.0

        # hold logic to keep position for h steps (5 calls)
        if 'hold' not in obs.state:
            obs.state['hold'] = 0
            obs.state['pos'] = 0.0
            obs.state['last_raw'] = 0.0
        if obs.state['hold'] > 0:
            obs.state['hold'] -= 1
            if obs.state['hold'] == 0:
                # decide to exit or continue based on current z
                if abs(z) < 0.6:
                    obs.state['pos'] = 0.0
                else:
                    # if still extreme in same direction, hold a bit longer
                    if (obs.state['pos'] > 0 and direction*z > 1.0) or (obs.state['pos'] < 0 and direction*z < -1.0):
                        obs.state['hold'] = 2
                        return {'IDX': float(obs.state['pos'])}
                    else:
                        obs.state['pos'] = 0.0
            return {'IDX': float(obs.state['pos'])}

        # not holding, consider entry
        if abs(raw) < 0.45:
            # flat signal, if currently flat stay flat, if holding position keep until hold expires
            if obs.state['pos'] != 0:
                # keep previous until hold logic decides
                return {'IDX': float(obs.state['pos'])}
            return {'IDX': 0.0}
        # enter
        obs.state['pos'] = raw
        obs.state['hold'] = 5  # 50 steps
        obs.state['last_raw'] = raw
        return {'IDX': float(raw)}
    except:
        return {}

