def signal(obs):
    try:
        a = obs.last('A','mid')
        b = obs.last('B','mid')
        c = obs.last('C','mid')
        idx = obs.last('IDX','mid')
        if any(v is None or np.isnan(v) for v in [a,b,c,idx]):
            return {}
        syn = 0.3333*a + 0.6667*b + 0.1667*c
        spread = idx - syn   # positive => IDX rich
        # scale: 60 cents ~ 1.6 std
        # dead zone 12 cents ~0.3 std
        if abs(spread) < 12:
            return {'IDX':0}
        t = -spread / 80.0   # 80 => 80c = 1.0 target; 40c=0.5 etc
        if t>1: t=1
        if t<-1: t=-1
        return {'IDX': float(t)}
    except:
        return {}

