def signal(obs):
    # momentum on A, IDX using past 10 return scaled
    s=obs.state
    targets={}
    for ass in ['A','B','C','IDX']:
        rm=obs.hist(ass,'mid',30)
        if len(rm)<20:
            continue
        # past 10-step return
        past = rm[-1]-rm[-11] if rm[-11]==rm[-11] and rm[-1]==rm[-1] else 0
        # normalize by recent vol
        # compute std of 10-step returns over window
        rets=[]
        for i in range(len(rm)-10):
            a=rm[i+10]-rm[i]
            if a==a:
                rets.append(a)
        if len(rets)<10:
            continue
        m=sum(rets)/len(rets)
        var=sum((x-m)**2 for x in rets)/len(rets)
        std=(var)**0.5 if var>1e-9 else 10
        if std<2: std=2
        z=past/std
        # momentum: follow sign
        # dead zone
        if abs(z)<0.3:
            t=0
        else:
            # cap
            zc=max(-2.5,min(2.5,z))
            t=max(-1,min(1,zc*0.4))
        targets[ass]=t
        # zero fee preference: also include X listings but keep zero
        if ass=='A':
            targets['A.X']=0
        if ass=='B':
            targets['B.X']=0
        if ass=='C':
            targets['C.X']=0
    return targets

def corr(a,b):
    mask=~(np.isnan(a)|np.isnan(b))
    a=a[mask]; b=b[mask]
    if len(a)<10: return 0
    ma=float(np.mean(a)); mb=float(np.mean(b))
    num=float(np.sum((a-ma)*(b-mb)))
    da=float(np.sqrt(np.sum((a-ma)**2)))
    db=float(np.sqrt(np.sum((b-mb)**2)))
    return num/(da*db) if da*db!=0 else 0

