def sim_mom(ass, past_h, hold, thresh):
    mid=np.array(H[ass]['mid'],float)
    n=len(mid)
    half=halves[ass]
    pnl_g=0; pnl_n=0; trades=0
    pos=0
    hold_cnt=0
    # threshold in price units, not z
    for t in range(past_h, n-1):
        if hold_cnt>0:
            hold_cnt-=1
        else:
            past = mid[t]-mid[t-past_h] if not (np.isnan(mid[t]) or np.isnan(mid[t-past_h])) else 0
            desired=pos
            if past > thresh:
                desired=1
            elif past < -thresh:
                desired=-1
            else:
                desired=0
                # we may want to keep pos if within deadband? For now flat if not exceeding thresh
            if desired!=pos:
                cost=abs(desired-pos)*half
                pnl_n-=cost
                pos=desired
