    s = obs.state
    if 'hold' not in s:
        s['hold'] = 0
        s['pos'] = 0
    if s['hold'] > 0:
        s['hold'] -= 1
    else:
        ha = obs.hist('A', 'mid', 60)
        # need at least 51 points to compute 50-step past return
        if len(ha) >= 51:
            cur = ha[-1]
            prev = ha[-51]
            # check not NaN (NaN != NaN)
            if cur == cur and prev == prev:
                past = cur - prev
                thr = 12.0
                desired = 0
                if past > thr:
                    desired = 1
                elif past < -thr:
                    desired = -1
                else:
                    desired = 0
                if desired != s['pos']:
                    s['pos'] = desired
                    if desired != 0:
                        s['hold'] = 4
                    else:
                        s['hold'] = 1
                else:
                    # keep holding without extra hold if same signal
                    if desired == 0:
                        s['hold'] = 0
            else:
                # missing data stay flat
                if s['pos'] != 0:
                    s['pos'] = 0
                    s['hold'] = 1
    p = s['pos']
